// NALAYAK transactional email service.
// Welcome email templates are generated by the backend.

const apiBase = () => process.env.REACT_APP_BACKEND_URL;

const getStoredUser = () => {
  try {
    const user = JSON.parse(
      localStorage.getItem('nalayak_user') || 'null'
    );

    if (user?.email) return user;
  } catch {
    // Continue to the membership fallback.
  }

  return null;
};

const sendRequest = async (path, body) => {
  const base = apiBase();

  if (!base) {
    throw new Error('Backend URL is not configured.');
  }

  const response = await fetch(`${base}${path}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  let data = null;

  try {
    data = await response.json();
  } catch {
    // The server may return a non-JSON response.
  }

  if (!response.ok) {
    const message =
      data?.detail ||
      data?.error?.message ||
      `Request failed with status ${response.status}`;

    throw new Error(message);
  }

  return data;
};

export const sendWelcomeEmail = async (kind = 'member') => {
  try {
    const user = getStoredUser();

    if (!user?.email) {
      console.warn(
        '[NALAYAK EMAIL] No saved user email. Welcome email skipped.'
      );
      return { status: 'skipped', reason: 'missing_email' };
    }

    const result = await sendRequest('/api/email/welcome', {
      email: user.email,
      name: user.name || '',
      kind: kind === 'club' ? 'club' : 'member',
    });

    console.info('[NALAYAK EMAIL] Welcome email result:', result.status);

    return result;
  } catch (error) {
    console.error('[NALAYAK EMAIL] Welcome email failed:', error);
    return { status: 'failed', error: error.message };
  }
};

export const registerDropAlert = async (slug) => {
  try {
    const user = getStoredUser();

    if (!user?.email) {
      console.warn(
        '[NALAYAK EMAIL] No saved user email. Drop alert skipped.'
      );
      return { status: 'skipped', reason: 'missing_email' };
    }

    const result = await sendRequest('/api/alerts/register', {
      email: user.email,
      slug,
    });

    console.info('[NALAYAK EMAIL] Drop alert result:', result.status);

    return result;
  } catch (error) {
    console.error('[NALAYAK EMAIL] Drop alert registration failed:', error);
    return { status: 'failed', error: error.message };
  }
};